#include <bits/stdc++.h>
#include "json.hpp"
using namespace std;using J=nlohmann::json;
J load(string p){ifstream f(p);f.exceptions(ios::badbit|ios::failbit);J j;f>>j;return j;}
int main(int argc,char**argv){J old=load(argv[1]),map=load(string(argv[2])+"/OLD-TO-NEW.json"),rc=load(string(argv[2])+"/receipt.json"),out=J::array(),drop=J::array();int cut=rc["last_initial_D0_dirty_read"],rank=0;set<int>piv,don;for(auto z:old["candidates"]){if(z["cut"].get<int>()!=520031)throw runtime_error("unexpected original cut");vector<int>r;bool ok=true;for(int x:z["roles"]){int v=map.at(to_string(x));if(v<0)ok=false;else r.push_back(v);}int p=map.at(to_string(z["pivot"].get<int>()));if(!ok||p<0){drop.push_back(z);continue;}sort(r.begin(),r.end());if(!piv.insert(p).second)throw runtime_error("duplicate pivot");for(int d:r)if(d!=p)don.insert(d);J w={{"roles",r},{"pivot",p},{"cut",cut},{"dim",z["dim"]},{"basis",z["basis"]},{"kind","SINK_REMAPPED_FRESH_GEN4_KERNEL"},{"old_pivot",z["pivot"]},{"old_cut",z["cut"]}};out.push_back(w);rank+=z["dim"].get<int>();}for(int p:piv)if(don.count(p))throw runtime_error("pivot donor overlap");J result={{"candidates",out},{"entrance_rank_before_mod3",rank},{"dropped_rows",drop},{"cut",cut},{"scope","Exact physical role remap only; fresh prefix, geometry and complete word replay required"}};ofstream f(argv[3]);f.exceptions(ios::badbit|ios::failbit);f<<result.dump(2)<<"\n";cerr<<"mapped="<<out.size()<<" dropped="<<drop.size()<<" rank="<<rank<<" cut="<<cut<<"\n";}
